/* @autogenerated */
import { Signal } from '@angular/core';
import type { RepositoryMetadata } from './repository.service';

export interface Tick<T, F> extends Signal<T | undefined> {
  searching: Signal<boolean>;
  fetch(filter: F): Tick<T, F>;
  reset(): Tick<T, F>;
  subscribe(callback: (value: T | undefined) => void): void;
}
export interface Shift<T, F> extends Signal<T | undefined> {
  searching: Signal<boolean>;
  fetch(filter: F): Shift<T, F>;
  reset(): Shift<T, F>;
  next(): Shift<T, F>;
  subscribe(callback: (value: T | undefined) => void): void;
}

export interface UpdateOptions<T> {
  /**
   * Valor que se cargó al empezar a editar. Con él, un 412 se emite como `EditConflictError` con las tres versiones
   * (original, enviada y actual) en lugar de llegar al aviso global.
   */
  original?: T;
}

/**
 * Qué resolver de un elemento: cada clave es un campo y su valor, lo que se quiere de él. Una referencia se sustituye
 * por la entidad referenciada (y se sigue con su subárbol); un campo que no es referencia se deja tal cual, así que
 * `{ model: { vendor: { name: {} } } }` equivale a `{ model: { vendor: {} } }`.
 */
export interface ProjectionSpec {
  [field: string]: ProjectionSpec;
}

/** Árbol de proyección a partir de rutas con puntos: `['site.client', 'model.vendor.name']`. */
export function projectionSpec(paths: readonly string[]): ProjectionSpec {
  const root: ProjectionSpec = {};
  paths.forEach((path) =>
    path
      .split('.')
      .filter((part) => !!part)
      .reduce((node, part) => (node[part] ??= {}), root),
  );
  return root;
}

/**
 * Hijos de tipo `P` que se quieren en cada fila de una proyección: los elementos de otro repositorio cuya referencia
 * `field` apunta a la fila. Lo crea el `children()` del repositorio del hijo, que aporta su tipo; el padre no necesita
 * conocerlo. `P` solo existe en compilación (marca fantasma).
 */
export interface Children<P> {
  /** Repositorio de los hijos. */
  readonly meta: RepositoryMetadata<any, any>;
  /** Campo de referencia del hijo que apunta al padre (`client`). */
  readonly field: string;
  /** Filtro del listado del hijo que acepta varias claves de padre (`clients`). */
  readonly filter: string;
  /** Referencias a proyectar en cada hijo, como en `projections`. */
  readonly include: ProjectionSpec | readonly string[];
  /** Hijos de cada hijo. */
  readonly children: ChildrenMap;
  readonly __of?: P;
}

/** Hijos pedidos en una proyección, por el nombre del campo con el que aparecen en cada fila. */
export type ChildrenMap = Record<string, Children<any>>;

/** Campos que añaden a cada fila los hijos de `C`: un `Signal` con su lista, `undefined` mientras carga. */
export type WithChildren<C extends ChildrenMap> = {
  [K in keyof C]: Signal<(C[K] extends Children<infer P> ? P : never)[] | undefined>;
};

/**
 * Tipos de una entidad para las proyecciones: su valor y, por cada referencia, los tipos de la entidad referenciada.
 * Los genera el modelo de cada entidad (`SiteTypes = { value: Site; refs: { client: ClientTypes } }`).
 */
export interface EntityTypes {
  value: object;
  refs: object;
}

/** Primer tramo de una ruta (`'model.vendor'` → `'model'`). */
type PathHead<P> = P extends `${infer H}.${string}` ? H : P;
/** Lo que sigue a `K` en una ruta (`'model.vendor'` con `'model'` → `'vendor'`). */
type PathTail<P, K extends string> = P extends `${K}.${infer R}` ? R : never;

/**
 * El valor de `E` tal como lo devuelve una proyección con las rutas `P`: las referencias pedidas son un `Signal` de
 * su entidad (proyectada a su vez con el resto de la ruta) y las demás siguen siendo `{ $ref }`. Con
 * `projections(['model.vendor'])`, `row.model()?.vendor()?.name` compila y `row.model()?.type()` no.
 */
export type Projected<E extends EntityTypes, P extends string> = {
  [K in keyof E['value']]: K extends keyof E['refs'] & PathHead<P>
    ? Signal<Projected<E['refs'][K] & EntityTypes, PathTail<P, K & string>> | null>
    : E['value'][K];
};
